491     fn refresh_fill_status(&mut self) {
492         if matches!(
493             self.status,
494             BoltV3BasketExecutionStatus::Stuck | BoltV3BasketExecutionStatus::Closed
495         ) || self.settled
496         {
497             return;
498         }
499         let overfilled = self
500             .legs
501             .iter()
502             .any(|leg| leg.filled_quantity > leg.target_quantity);
503         if overfilled {
504             self.status = BoltV3BasketExecutionStatus::Stuck;
505             self.unresolved_real_exposure = true;
506             self.reservation_held = true;
507             return;
508         }
509         let any_fill = self
510             .legs
511             .iter()
512             .any(|leg| leg.filled_quantity > Decimal::ZERO);
513         let complete = self
514             .legs
515             .iter()
516             .all(|leg| leg.filled_quantity >= leg.target_quantity);
517         if complete {
518             self.status = BoltV3BasketExecutionStatus::Complete;
519             self.unresolved_real_exposure = false;
520         } else if any_fill {
521             self.status = BoltV3BasketExecutionStatus::Partial;
522             self.unresolved_real_exposure = true;
523         }
524     }

