291	fn references_retired_registry_type(tokens: &[Token], type_name: &str) -> bool {
292	    let actual = texts(tokens);
293	    for start in 0..actual.len().saturating_sub(4) {
294	        if actual[start..start + 4] == ["strategies", "::", "registry", "::"] {
295	            if actual.get(start + 4) == Some(&type_name) {
296	                return true;
297	            }
298	            if use_tree_contains_at_depth(&actual, start + 4, type_name) {
299	                return true;
300	            }
301	        }
302	        if actual[start..start + 3] == ["strategies", "::", "{"] {
303	            let mut depth = 1usize;
304	            let mut cursor = start + 3;
305	            while cursor < actual.len() && depth > 0 {
306	                match actual[cursor] {
307	                    "{" => depth += 1,
308	                    "}" => depth -= 1,
309	                    "registry"
310	                        if depth == 1
311	                            && actual.get(cursor + 1) == Some(&"::")
312	                            && is_use_tree_segment_start(&actual, cursor) =>
313	                    {
314	                        if actual.get(cursor + 2) == Some(&type_name)
315	                            || use_tree_contains_at_depth(&actual, cursor + 2, type_name)
316	                        {
317	                            return true;
318	                        }
319	                    }
320	                    _ => {}
321	                }
322	                cursor += 1;
323	            }
324	        }
325	    }
326	    false
327	}
328	
329	fn use_tree_contains_at_depth(actual: &[&str], open_brace: usize, type_name: &str) -> bool {
330	    if actual.get(open_brace) != Some(&"{") {
331	        return false;
332	    }
333	    let mut depth = 1usize;
334	    let mut cursor = open_brace + 1;
335	    while cursor < actual.len() && depth > 0 {
336	        match actual[cursor] {
337	            "{" => depth += 1,
338	            "}" => depth -= 1,
339	            name
340	                if depth == 1
341	                    && name == type_name
342	                    && is_use_tree_segment_start(actual, cursor) =>
343	            {
344	                return true;
345	            }
346	            _ => {}
347	        }
348	        cursor += 1;
349	    }
350	    false
351	}
352	
353	fn is_use_tree_segment_start(actual: &[&str], index: usize) -> bool {
354	    matches!(actual.get(index.wrapping_sub(1)), Some(&"{") | Some(&","))
355	}
