364	fn public_declaration_tokens(tokens: &[Token]) -> Vec<&str> {
365	    let mut public = Vec::new();
366	    for (start, token) in tokens.iter().enumerate() {
367	        if token.text != "pub" {
368	            continue;
369	        }
370	        let mut cursor = start;
371	        let mut parentheses = 0usize;
372	        let mut brackets = 0usize;
373	        let mut angles = 0usize;
374	        while let Some(current) = tokens.get(cursor) {
375	            public.push(current.text.as_str());
376	            match current.text.as_str() {
377	                "(" => parentheses += 1,
378	                ")" => parentheses = parentheses.saturating_sub(1),
379	                "[" => brackets += 1,
380	                "]" => brackets = brackets.saturating_sub(1),
381	                "<" => angles += 1,
382	                ">" => angles = angles.saturating_sub(1),
383	                "{" | ";" | "," if parentheses == 0 && brackets == 0 && angles == 0 => break,
384	                _ => {}
385	            }
386	            cursor += 1;
387	        }
388	    }
389	    public
390	}
