#!/usr/bin/env python3
"""Faithful Python port of tests/bolt_v3_strategy_substrate_structure.rs.

Predicts pass/fail of the never-compiled Rust structure test before it is
registered into the wiring_registration harness. Mirrors the Rust tokenizer
and every #[test] body 1:1.
"""
import os
import sys

REPO = "/Users/spson/Projects/Claude/bolt-v2"

ARCHETYPES = [
    "src/strategies/binary_oracle_edge_taker/archetype.rs",
    "src/strategies/binary_oracle_maker/archetype.rs",
    "src/strategies/complete_set_arbitrage/archetype.rs",
]


def repo_path(rel):
    return os.path.join(REPO, rel) if rel else REPO


def ident_start(b):
    return (65 <= b <= 90) or (97 <= b <= 122) or b == 95


def ident_continue(b):
    return ident_start(b) or (48 <= b <= 57)


def scan_nested_block_comment(data, index):
    depth = 0
    while index < len(data):
        if data[index:index + 2] == b"/*":
            depth += 1
            index += 2
        elif data[index:index + 2] == b"*/":
            depth -= 1
            index += 2
            if depth == 0:
                return index
        else:
            index += 1
    return index


def scan_raw_string(data, index):
    cursor = index
    if cursor < len(data) and data[cursor:cursor + 1] == b"b":
        cursor += 1
    if cursor >= len(data) or data[cursor:cursor + 1] != b"r":
        return None
    cursor += 1
    hashes = 0
    while cursor < len(data) and data[cursor:cursor + 1] == b"#":
        hashes += 1
        cursor += 1
    if cursor >= len(data) or data[cursor:cursor + 1] != b'"':
        return None
    cursor += 1
    while cursor < len(data):
        if data[cursor:cursor + 1] == b'"' and all(
            data[cursor + off:cursor + off + 1] == b"#" for off in range(1, hashes + 1)
        ):
            return cursor + hashes + 1
        cursor += 1
    return cursor


def scan_quoted_literal(data, index):
    cursor = index
    if cursor < len(data) and data[cursor:cursor + 1] == b"b":
        cursor += 1
    if cursor >= len(data) or data[cursor:cursor + 1] != b'"':
        return None
    cursor += 1
    while cursor < len(data):
        if data[cursor:cursor + 1] == b"\\":
            cursor += 2
        elif data[cursor:cursor + 1] == b'"':
            return cursor + 1
        else:
            cursor += 1
    return cursor


def scan_char_or_lifetime(data, index):
    cursor = index
    if data[cursor:cursor + 1] == b"b" and data[cursor + 1:cursor + 2] == b"'":
        cursor += 1
    if data[cursor:cursor + 1] != b"'":
        return None
    nxt = data[cursor + 1:cursor + 2]
    if nxt and ident_start(nxt[0]) and data[cursor + 2:cursor + 3] != b"'":
        cursor += 2
        while cursor < len(data) and ident_continue(data[cursor]):
            cursor += 1
        return cursor
    cursor += 1
    while cursor < len(data):
        if data[cursor:cursor + 1] == b"\\":
            cursor += 2
        elif data[cursor:cursor + 1] == b"'":
            return cursor + 1
        else:
            cursor += 1
    return cursor


def tokenize(source):
    data = source.encode("utf-8")
    tokens = []
    index = 0
    while index < len(data):
        b = data[index]
        if bytes([b]).isspace():
            index += 1
            continue
        if data[index:index + 2] == b"//":
            index += 2
            while index < len(data) and data[index] != 0x0A:
                index += 1
            continue
        if data[index:index + 2] == b"/*":
            index = scan_nested_block_comment(data, index)
            continue
        end = scan_raw_string(data, index)
        if end is not None:
            index = end
            continue
        end = scan_quoted_literal(data, index)
        if end is not None:
            index = end
            continue
        end = scan_char_or_lifetime(data, index)
        if end is not None:
            index = end
            continue
        if data[index:index + 2] == b"r#" and index + 2 < len(data) and ident_start(data[index + 2]):
            start = index + 2
            index = start + 1
            while index < len(data) and ident_continue(data[index]):
                index += 1
            tokens.append(data[start:index].decode("utf-8"))
            continue
        if ident_start(b):
            start = index
            index += 1
            while index < len(data) and ident_continue(data[index]):
                index += 1
            tokens.append(data[start:index].decode("utf-8"))
            continue
        if data[index:index + 2] == b"::":
            tokens.append("::")
            index += 2
            continue
        tokens.append(chr(b))
        index += 1
    return tokens


def source_tokens(rel):
    with open(repo_path(rel), encoding="utf-8") as fh:
        return tokenize(fh.read())


def count_sequence(tokens, expected):
    n = len(expected)
    return sum(1 for i in range(len(tokens) - n + 1) if tokens[i:i + n] == list(expected))


def contains_sequence(tokens, expected):
    return count_sequence(tokens, expected) > 0


def references_crate_strategies(tokens):
    if contains_sequence(tokens, ["crate", "::", "strategies"]) or contains_sequence(
        tokens, ["super", "::", "strategies"]
    ):
        return True
    actual = tokens
    for start in range(max(0, len(actual) - 3)):
        if actual[start:start + 4] != ["use", "crate", "::", "{"]:
            continue
        depth = 1
        cursor = start + 4
        while cursor < len(actual) and depth > 0:
            t = actual[cursor]
            if t == "{":
                depth += 1
            elif t == "}":
                depth -= 1
            elif t == "strategies":
                return True
            cursor += 1
    return False


def is_use_tree_segment_start(actual, index):
    return index >= 1 and actual[index - 1] in ("{", ",")


def use_tree_contains_at_depth(actual, open_brace, type_name):
    if open_brace >= len(actual) or actual[open_brace] != "{":
        return False
    depth = 1
    cursor = open_brace + 1
    while cursor < len(actual) and depth > 0:
        t = actual[cursor]
        if t == "{":
            depth += 1
        elif t == "}":
            depth -= 1
        elif depth == 1 and t == type_name and is_use_tree_segment_start(actual, cursor):
            return True
        cursor += 1
    return False


def references_retired_registry_type(tokens, type_name):
    actual = tokens
    for start in range(max(0, len(actual) - 4)):
        if actual[start:start + 4] == ["strategies", "::", "registry", "::"]:
            if start + 4 < len(actual) and actual[start + 4] == type_name:
                return True
            if use_tree_contains_at_depth(actual, start + 4, type_name):
                return True
        if actual[start:start + 3] == ["strategies", "::", "{"]:
            depth = 1
            cursor = start + 3
            while cursor < len(actual) and depth > 0:
                t = actual[cursor]
                if t == "{":
                    depth += 1
                elif t == "}":
                    depth -= 1
                elif (
                    t == "registry"
                    and depth == 1
                    and cursor + 1 < len(actual)
                    and actual[cursor + 1] == "::"
                    and is_use_tree_segment_start(actual, cursor)
                ):
                    if (cursor + 2 < len(actual) and actual[cursor + 2] == type_name) or \
                            use_tree_contains_at_depth(actual, cursor + 2, type_name):
                        return True
                cursor += 1
    return False


def rust_files_below(root):
    files = []

    def collect(path):
        for entry in sorted(os.listdir(path)):
            full = os.path.join(path, entry)
            if os.path.isdir(full):
                if entry == "target":
                    continue
                collect(full)
            elif entry.endswith(".rs"):
                files.append(full)

    collect(root)
    files.sort()
    return files


def production_bolt_v3_files():
    src = repo_path("src")
    files = []
    for entry in sorted(os.listdir(src)):
        if not entry.startswith("bolt_v3_"):
            continue
        full = os.path.join(src, entry)
        if os.path.isdir(full):
            files.extend(rust_files_below(full))
        elif entry.endswith(".rs"):
            files.append(full)
    files.sort()
    return files


def relative(path):
    return os.path.relpath(path, REPO).replace("\\", "/")


def public_declaration_tokens(tokens):
    public = []
    for start, token in enumerate(tokens):
        if token != "pub":
            continue
        cursor = start
        parens = brackets = angles = 0
        while cursor < len(tokens):
            current = tokens[cursor]
            public.append(current)
            if current == "(":
                parens += 1
            elif current == ")":
                parens = max(0, parens - 1)
            elif current == "[":
                brackets += 1
            elif current == "]":
                brackets = max(0, brackets - 1)
            elif current == "<":
                angles += 1
            elif current == ">":
                angles = max(0, angles - 1)
            elif current in ("{", ";", ",") and parens == 0 and brackets == 0 and angles == 0:
                break
            cursor += 1
    return public


FAILURES = []


def check(name, fn):
    try:
        fn()
        print(f"PASS {name}")
    except AssertionError as exc:
        FAILURES.append(name)
        print(f"FAIL {name}: {exc}")


def t_tokenizer_controls():
    controls = tokenize(
        "\n"
        "        // crate::strategies::fake::KEY clients.get resolve_fee_provider\n"
        "        /* nested /* crate::strategies::fake */ clients.get */\n"
        '        const TEXT: &str = "crate::strategies::fake::KEY clients.get";\n'
        '        const RAW: &str = r#"resolve_fee_provider crate::strategies"#;\n'
        "        const CH: char = 'g';\n"
        "        fn visible<'a>(value: &'a str) { assemble_strategy_build_context(value); }\n"
        "        "
    )
    assert count_sequence(controls, ["crate", "::", "strategies"]) == 0, "comment leak"
    assert count_sequence(controls, ["clients", ".", "get"]) == 0, "string leak"
    assert count_sequence(controls, ["resolve_fee_provider"]) == 0, "raw-string leak"
    assert count_sequence(controls, ["assemble_strategy_build_context"]) == 1, "visible code lost"


def t_matcher_fixtures():
    for source in [
        "use bolt_v2::strategies::registry::FeeProvider;",
        "use bolt_v2::strategies::registry::{FeeProvider, StrategyBuilder};",
        "use bolt_v2::strategies::{registry::FeeProvider, production_strategy_registry};",
        "use bolt_v2::strategies::{registry::{FeeProvider, StrategyBuildContext}};",
    ]:
        assert references_retired_registry_type(tokenize(source), "FeeProvider"), source
    unrelated = tokenize(
        "use other::registry::{FeeProvider}; use bolt_v2::strategies::production_strategy_registry; "
        "use bolt_v2::strategies::registry::{nested::FeeProvider}; "
        "use bolt_v2::strategies::{nested::{registry::FeeProvider}};"
    )
    assert not references_retired_registry_type(unrelated, "FeeProvider"), "negative fixture matched"


